python3 << 'EOF'
import pandas as pd, io, json, numpy as np

def load(fid):
    p=f'/app/dataset/production_{fid}.csv'
    raw=open(p,'rb').read()
    enc='utf-16' if raw[:2] in (b'\xff\xfe',b'\xfe\xff') else 'utf-8'
    lines=raw.decode(enc).splitlines()
    for i,l in enumerate(lines):
        if l.lstrip().startswith('timestamp'): break
    sep=';' if ';' in lines[i] else ','
    return pd.read_csv(io.StringIO('\n'.join(lines[i:])), sep=sep, dtype=str)

def cv(x):
    x=str(x).strip()
    if x in ('nan','','None'): return np.nan
    if ',' in x: x=x.replace('.','').replace(',','.')
    try: return float(x)
    except: return np.nan

mx={}
for fid in ['FARM_'+c for c in 'ABCDEFGHIJKLMNOPQRSTUVWX']:
    df=load(fid)
    t=df['inverter_temperature_C'].map(cv)
    mx[fid]=t.max()
    over=df[t>85.0]
    if len(over):
        print(fid, 'RAW rows with temp>85:')
        print(over.iloc[:, [0,1]].to_string())
print('max temps:', {k:round(v,1) for k,v in mx.items()})
EOF

